def load() -> pd.DataFrame:
    import glob
    files = sorted(glob.glob('data/environment/input/water-body-testing-*.csv'))
    dfs = []
    for file in files:
        df = pd.read_csv(file)
        dfs.append(df)
    return pd.concat(dfs, ignore_index=True)

def process(freshwater_samples) -> pd.DataFrame:
    df = freshwater_samples.copy()
    df['is_exceedance'] = df['Violation'].str.lower() == 'yes'

    yearly_stats = df.groupby('Year').agg(
        total_samples=('is_exceedance', 'count'),
        exceedances=('is_exceedance', 'sum')
    ).reset_index()

    yearly_stats['exceedance_rate'] = (yearly_stats['exceedances'] / yearly_stats['total_samples'] * 100).round(2)

    return yearly_stats.sort_values('Year')

def process(exceedance_by_year) -> pd.DataFrame:
    avg_rate = exceedance_by_year['exceedance_rate'].mean()
    return pd.DataFrame({'average_exceedance_rate': [round(avg_rate, 2)]})
